make -j$(nproc) all
$CC $CFLAGS -c -std=c99 -Isrc     "$SRC/hoextdown/test/hoedown_fuzzer.c" -o $WORK/hoedown_fuzzer.o
$CXX $CXXFLAGS -std=c++11 -Isrc     $WORK/hoedown_fuzzer.o -o $OUT/hoedown_fuzzer     $LIB_FUZZING_ENGINE "$SRC/hoextdown/libhoedown.a"
cp $SRC/*.options $OUT/
cp $SRC/*.dict $OUT/
mkdir -p corpus
find $SRC/hoextdown/test -type f -name '*.text' | while read in_file
do
  out_file=$(sha1sum "$in_file" | cut -c 1-32)
  cat "$in_file" >> "corpus/$out_file"
done
zip -j $OUT/hoextdown_fuzzer_corpus.zip corpus/*
